const toggle=document.querySelector('.menu-toggle');const menu=document.querySelector('#mobile-menu');function closeMenu(){toggle.setAttribute('aria-expanded','false');menu.hidden=true;}toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));menu.hidden=open;});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!menu.hidden){closeMenu();toggle.focus();}});menu.addEventListener('click',event=>{if(event.target.closest('a'))closeMenu();});document.addEventListener('focusin',event=>{if(!menu.hidden&&!menu.contains(event.target)&&event.target!==toggle)closeMenu();});matchMedia('(min-width: 1100px)').addEventListener('change',event=>{if(event.matches)closeMenu();});document.querySelectorAll('a[href*="#"]').forEach(link=>link.addEventListener('click',()=>{const target=new URL(link.href);if(target.pathname!==location.pathname)return;const el=document.getElementById(target.hash.slice(1));if(el){el.tabIndex=-1;requestAnimationFrame(()=>el.focus({preventScroll:true}));}}));